CREATE TABLE "PlanCredito" (
  "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" TEXT NOT NULL, "sistema" TEXT NOT NULL, "tasaAnual" REAL NOT NULL, "numeroCuotas" INTEGER NOT NULL, "periodicidadMeses" INTEGER NOT NULL DEFAULT 1, "diasPrimeraCuota" INTEGER NOT NULL DEFAULT 30, "politicaAjuste" TEXT NOT NULL DEFAULT 'CUOTA_FIJA', "politicaMora" TEXT NOT NULL DEFAULT 'SIN_MORA', "politicaPagoAnticipado" TEXT NOT NULL DEFAULT 'REDUCIR_PLAZO', "tasaVariable" BOOLEAN NOT NULL DEFAULT false, "politicaRecalculo" TEXT NOT NULL DEFAULT 'AUTORIZADO', "moneda" TEXT NOT NULL DEFAULT 'PYG', "precisionMonetaria" INTEGER NOT NULL DEFAULT 0, "activo" BOOLEAN NOT NULL DEFAULT true, "creadoEn" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
